<script setup>
import { onMounted, ref } from 'vue'
import { ElMessage } from 'element-plus'
import * as learningApi from '../api/learning'
const progress=ref({topics:[]});const records=ref([]);const loading=ref(false);const form=ref({type:'READ',topic:'',durationMinutes:30,remark:''});const saving=ref(false)
async function load(){loading.value=true;try{const [p,r]=await Promise.all([learningApi.getLearningProgress({range:'30d'}),learningApi.listLearningRecords({page:1,pageSize:30})]);progress.value=p.data.data||{topics:[]};records.value=r.data.data?.rows||[]}catch(e){ElMessage.error(e.response?.data?.msg||'学习数据加载失败')}finally{loading.value=false}}
async function save(){if(!form.value.topic.trim())return ElMessage.warning('请输入学习主题');saving.value=true;try{await learningApi.createLearningRecord(form.value);ElMessage.success('已记录');form.value={type:'READ',topic:'',durationMinutes:30,remark:''};await load()}catch(e){ElMessage.error(e.response?.data?.msg||'记录失败')}finally{saving.value=false}}
onMounted(load)
</script>
<template><div class="page"><div class="page-heading"><div><h2>学习记录与进度</h2><p>记录学习行为，观察知识点掌握情况。番茄钟完成后会自动记录。</p></div><el-button type="primary" @click="$router.push('/pomodoro')">开始专注</el-button></div><el-row :gutter="16"><el-col :xs="24" :md="9"><el-card><template #header>记录一次学习</template><el-form label-position="top" @submit.prevent="save"><el-form-item label="类型"><el-select v-model="form.type"><el-option label="阅读" value="READ"/><el-option label="测验" value="QUIZ"/><el-option label="复习" value="REVIEW"/><el-option label="聊天" value="CHAT"/></el-select></el-form-item><el-form-item label="主题"><el-input v-model="form.topic"/></el-form-item><el-form-item label="时长（分钟）"><el-input-number v-model="form.durationMinutes" :min="0" :max="1440"/></el-form-item><el-form-item label="备注"><el-input v-model="form.remark" type="textarea"/></el-form-item><el-button type="primary" :loading="saving" native-type="submit">保存记录</el-button></el-form></el-card></el-col><el-col :xs="24" :md="15"><el-card><template #header>知识点进度</template><el-table v-loading="loading" :data="progress.topics" empty-text="暂无进度"><el-table-column prop="topic" label="主题"/><el-table-column label="掌握度"><template #default="scope"><el-progress :percentage="Number(scope.row.mastery||0)"/></template></el-table-column><el-table-column prop="quizAccuracy" label="测验正确率"/><el-table-column prop="studyMinutes" label="学习分钟"/></el-table></el-card></el-col></el-row><el-card class="records"><template #header>最近学习记录</template><el-table :data="records" empty-text="暂无记录"><el-table-column label="类型" width="100"><template #default="scope">{{({READ:'阅读',QUIZ:'测验',REVIEW:'复习',CHAT:'聊天',FOCUS:'专注'})[scope.row.type]||scope.row.type}}</template></el-table-column><el-table-column prop="topic" label="主题"/><el-table-column prop="durationMinutes" label="时长（分钟）" width="130"/></el-table></el-card></div></template>
<style scoped>.page{max-width:1300px;margin:0 auto}.page-heading{margin-bottom:16px}h2{margin:0 0 6px}p{color:#909399;margin:0}.records{margin-top:16px}</style>
